#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=8
ENV_FILE=".env.local"
SITE_URL="https://leapgrow.app"
CRON_URL="$SITE_URL/api/cron/devotion-reminders"

if [[ ! -f "$ENV_FILE" || ! -f supabase/migrations/0032_devotion_reminders.sql ]]; then
  printf 'Run this from The Leap project folder, after git pull:\n'
  printf '  cd "/Users/denisslyimo/Documents/PD/My Projects/The Leap" && git pull\n'
  exit 1
fi

SUPABASE_URL=$(_existing NEXT_PUBLIC_SUPABASE_URL)
SUPABASE_REF=${SUPABASE_URL#https://}
SUPABASE_REF=${SUPABASE_REF%%.*}
SQL_EDITOR="https://supabase.com/dashboard/project/$SUPABASE_REF/sql/new"

# to_clipboard VALUE: copies to the clipboard (macOS), or prints it if
# there's no clipboard tool, so a secret is never left visible by default.
to_clipboard() {
  if command -v pbcopy >/dev/null 2>&1; then
    printf '%s' "$1" | pbcopy
  else
    warn "no clipboard tool, so copy it from here:"
    printf '\n%s\n\n' "$1"
  fi
}

# call_sender: POSTs to the live reminder endpoint; prints "<body> <status>".
call_sender() {
  curl -s -X POST -H "Authorization: Bearer $CRON_SECRET" \
    -w ' %{http_code}' "$CRON_URL" || printf 'network-error 000'
}

banner "Daily devotion reminders (The Leap)"

# ── Stage 1: generate keys locally ─────────────────────────────────────────
stage "Generate notification keys and the cron secret"
say "Push notifications need a key pair (\"VAPID\" keys) that proves reminders"
say "come from The Leap, plus a secret so only our scheduler can trigger them."
if [[ -n "$(_existing VAPID_PRIVATE_KEY || true)" ]]; then
  note "Keys already exist in $ENV_FILE, so keeping them (new keys would break"
  note "every device that already turned reminders on)."
  NEXT_PUBLIC_VAPID_PUBLIC_KEY=$(_existing NEXT_PUBLIC_VAPID_PUBLIC_KEY)
  VAPID_PRIVATE_KEY=$(_existing VAPID_PRIVATE_KEY)
else
  KEYS=$(node -e '
    const ecdh = require("crypto").createECDH("prime256v1");
    ecdh.generateKeys();
    console.log(ecdh.getPublicKey("base64url") + " " + ecdh.getPrivateKey("base64url"));
  ')
  NEXT_PUBLIC_VAPID_PUBLIC_KEY=${KEYS% *}
  VAPID_PRIVATE_KEY=${KEYS#* }
fi
CRON_SECRET=$(_existing CRON_SECRET || openssl rand -hex 32)
VAPID_SUBJECT="$SITE_URL"
write_env NEXT_PUBLIC_VAPID_PUBLIC_KEY "$NEXT_PUBLIC_VAPID_PUBLIC_KEY"
write_env VAPID_PRIVATE_KEY "$VAPID_PRIVATE_KEY"
write_env VAPID_SUBJECT "$VAPID_SUBJECT"
write_env CRON_SECRET "$CRON_SECRET"
pause

# ── Stage 2: Supabase service role key ─────────────────────────────────────
stage "Supabase: copy the service role key"
say "The reminder sender runs with no signed-in user, so it needs Supabase's"
say "server-only key to see everyone's reminder settings."
open_url "https://supabase.com/dashboard/project/$SUPABASE_REF/settings/api-keys"
step "Open the 'Legacy API keys' tab (if you see one)."
step "On the 'service_role' row, click Reveal, then Copy."
note "No legacy tab? Under 'Secret keys', copy the default key (starts sb_secret_)."
warn "This key bypasses all security rules. Never share it or put it in the app's code."
ask_secret SUPABASE_SERVICE_ROLE_KEY "Paste the key (hidden):"
write_env SUPABASE_SERVICE_ROLE_KEY "$SUPABASE_SERVICE_ROLE_KEY"
pause

# ── Stage 3: Vercel env vars ───────────────────────────────────────────────
stage "Vercel: add the 5 settings"
open_url "https://vercel.com/dashboard"
step "Open the 'the-leap' project → Settings → Environment Variables."
say "For each one below, the value goes on your clipboard. In Vercel, type the"
say "name in 'Key', press ⌘V in 'Value', keep all environments ticked, and Save."
printf '\n'
for name in NEXT_PUBLIC_VAPID_PUBLIC_KEY VAPID_PRIVATE_KEY VAPID_SUBJECT CRON_SECRET SUPABASE_SERVICE_ROLE_KEY; do
  to_clipboard "${!name}"
  printf '  %s%s%s  %s(value copied)%s\n' "$BOLD" "$name" "$RESET" "$DIM" "$RESET"
  pause "Saved it in Vercel? Press Enter for the next one"
done
to_clipboard ""
confirm "All 5 saved in Vercel?" || SKIPPED+=("Add the missing Vercel environment variables, then redeploy")

# ── Stage 4: run migration 0032 ────────────────────────────────────────────
stage "Supabase: create the reminder tables"
to_clipboard "$(cat supabase/migrations/0032_devotion_reminders.sql)"
say "Migration 0032 is on your clipboard."
open_url "$SQL_EDITOR"
step "Click into the empty query box, press ⌘V, then click Run."
step "Expect: 'Success. No rows returned'."
note "If it says a table 'already exists', it was run before. That's fine."
pause "Ran it?"

# ── Stage 5: redeploy ──────────────────────────────────────────────────────
stage "Vercel: redeploy so the new settings take effect"
say "New settings only reach the site after a fresh deploy."
step "In the 'the-leap' project, open the Deployments tab."
step "On the latest Production deployment: '...' menu → Redeploy."
step "Wait until it shows 'Ready'."
pause "Redeployed and Ready?"

# ── Stage 6: check the live sender ─────────────────────────────────────────
stage "Check the live reminder sender"
say "Calling $CRON_URL with the secret…"
RESULT=$(call_sender)
CODE=${RESULT##* }
BODY=${RESULT% *}
say "Response: HTTP $CODE ${BODY:0:160}"
case "$CODE" in
  200) if [[ "$BODY" == "{"*'"sent"'* ]]; then
         note "Connected: the site, the secret and the database all work."
       else
         # The site answers unknown paths with an HTML page.
         warn "The reminder code isn't live yet. Check the latest deploy includes it."
         SKIPPED+=("Deploy the devotion reminder code, then re-run this wizard")
       fi ;;
  401) warn "Secret rejected. Check CRON_SECRET in Vercel matches, then redeploy."
       SKIPPED+=("Fix CRON_SECRET in Vercel and redeploy (sender returned 401)") ;;
  *)   warn "Unexpected response. Check SUPABASE_SERVICE_ROLE_KEY and migration 0032."
       SKIPPED+=("Sender returned $CODE: check Vercel settings and migration 0032") ;;
esac
pause

# ── Stage 7: schedule hourly ───────────────────────────────────────────────
stage "Supabase: run the sender every hour"
to_clipboard "create extension if not exists pg_cron;
create extension if not exists pg_net with schema extensions;

select cron.schedule(
  'devotion-reminders',
  '0 * * * *',
  \$\$
  select net.http_post(
    url := '$CRON_URL',
    headers := jsonb_build_object('Authorization', 'Bearer $CRON_SECRET')
  );
  \$\$
);"
say "The schedule SQL (with your secret filled in) is on your clipboard."
open_url "$SQL_EDITOR"
step "Open a new query, press ⌘V, then click Run."
step "Expect a single number back (the job id)."
note "Re-running it just updates the same 'devotion-reminders' job."
pause "Ran it?"
to_clipboard ""

# ── Stage 8: try it on your device ─────────────────────────────────────────
stage "Try it: send yourself a reminder now"
say "Opening the devotion page marks today's devotion as read, and readers"
say "are skipped, so we'll clear just your own read mark before sending."
open_url "$SITE_URL/evolve/devotion"
step "On the 'Daily reminder' card, pick the current hour, tap 'Remind me daily',"
step "and allow notifications when the browser asks."
ask TEST_EMAIL "The email you sign in to The Leap with:"
to_clipboard "delete from devotion_reads
where user_id = (select id from profile_emails where email = '$TEST_EMAIL');"
step "That SQL is on your clipboard: run it in a new Supabase SQL query."
open_url "$SQL_EDITOR"
pause "Turned the reminder on and ran the SQL? Press Enter to send"
RESULT=$(call_sender)
say "Response: HTTP ${RESULT##* } $(printf '%.160s' "${RESULT% *}")"
note "Expect \"sent\":1 and a notification within a few seconds."
confirm "Did the notification arrive?" ||
  SKIPPED+=("Test reminder didn't arrive: check notifications are allowed for your browser in System Settings → Notifications")

finish
